/**
 * @file isApplePlatform.ts
 * @input Reads navigator.userAgentData.platform and navigator.platform
 * @output Exports isApplePlatform
 * @position Internal util; the single platform detection behind useHotkeys and Kbd
 *
 * Deliberately absent from utils/index.ts: packages/core/src/index.ts does
 * `export * from './utils'`, so naming it there would publish it as API.
 * Import it by path, as interactionModality is imported.
 */

/**
 * Detects whether the current platform is macOS/iOS.
 * Prefers the User-Agent Client Hints API when it names a platform (modern
 * Chrome/Edge), falls back to navigator.platform (deprecated but universally
 * supported) when it names none.
 */
export function isApplePlatform(): boolean {
  if (typeof navigator === 'undefined') {
    return false;
  }
  const uaData = 'userAgentData' in navigator ? navigator.userAgentData : null;
  if (uaData && typeof uaData === 'object' && 'platform' in uaData) {
    const uaPlatform = (uaData as {platform?: unknown}).platform;
    const named = typeof uaPlatform === 'string' ? uaPlatform.trim() : '';
    // A value that names nothing is no answer, not a negative one: builds that
    // rewrite their client-hints identity ship '', and 'Unknown' is the spec's
    // own sentinel for "cannot say". Both fall through rather than reading as
    // "not Apple".
    if (named !== '' && named.toLowerCase() !== 'unknown') {
      return /mac/i.test(named);
    }
  }
  return /Mac|iPhone|iPad|iPod/.test(navigator.platform ?? '');
}

// Copyright (c) Meta Platforms, Inc. and affiliates.

/**
 * @file sharedRealm.ts
 * @input A registered name and its protocol version
 * @output One value per key in the JavaScript realm, shared by every copy of
 *   Core
 * @position Shared runtime state for stores and contexts; no React and no
 *   client directive, so server-safe modules can use it
 */

/**
 * The registered key of a shared value. The version names the value's shape.
 * Change it when a copy built against the old shape cannot read the value.
 * Each copy then keeps its own value.
 */
export function sharedKey(name: string, version: number): symbol {
  return Symbol.for(`@astryxdesign/core/${name}/v${version}`);
}

/**
 * The value under `key` in this JavaScript realm, created on first use. Every
 * copy of Core that asks for the same key gets the same value.
 *
 * The key names the protocol version, so a value found under it has this
 * protocol's shape. `accepts` guards against a key collision: a value it
 * rejects is left in place, and this copy keeps a value of its own.
 */
export function realmValue<T>(
  key: symbol,
  create: () => T,
  accepts: (value: unknown) => boolean = () => true,
): T {
  const realm = globalThis as typeof globalThis & {[key: symbol]: unknown};
  if (Object.hasOwn(realm, key)) {
    const existing = realm[key];
    return accepts(existing) ? (existing as T) : create();
  }
  const value = create();
  realm[key] = value;
  return value;
}
